typedef unsigned int uint32_t;
typedef unsigned long size_t;
void* malloc(size_t);
void memcpy(void*, const void*, size_t);
void flash_write(uint32_t, const void*, size_t);

typedef struct { uint32_t offset; uint32_t length; const void* data; } ota_chunk_t;

void ota_apply_chunk(ota_chunk_t* chunk, uint32_t flash_base)
{
  void* buf = malloc(chunk->length);
  memcpy(buf, chunk->data, chunk->length);
  flash_write(flash_base + chunk->offset, buf, chunk->length);
}

int ota_get_version(void)
{
  return 42;
}
